"""Exercise production installation health checks using local fixtures only."""
from pathlib import Path
import os,subprocess,tempfile
root=Path(__file__).resolve().parents[1]
s=(root/'src/ui.c').read_text();a=s.index('static int health_panel(');b=s.index('static void dependencies_ui(void)',a)
prelude='\n#include <assert.h>\n#include <stdio.h>\n#include <string.h>\n#include "amihass_config.h"\n#include "nd_panel.h"\n#define AMIHASS_PORT "AmiHASS.Service"\nstruct Library {int n;};struct NDPanel {int n;};static struct Library lib;static struct NDPanel panel;static int mode,opens,checks;\nstatic void Forbid(void){}static void Permit(void){}static void *FindPort(const char *n){(void)n;return mode ? &panel:NULL;}\nstatic int dependency_path(const char *p){return mode&&!strcmp(p,"C:curl")?1:mode==2;}\nint amihass_config_load(struct AmiHASSConfig *c){memset(c,0,sizeof(*c));strcpy(c->service_dir,"SYS:Utilities/AmiHASS");strcpy(c->token,"PRIVATE-FIXTURE-TOKEN");strcpy(c->connection.url,"https://private.invalid");c->recovered=mode==2;return mode!=0;}\nstatic struct Library *OpenLibrary(const char *n,int v){(void)n;(void)v;return mode ? &lib:NULL;}static void CloseLibrary(struct Library *l){assert(l==&lib);}\nstatic int GetVar(const char *n,char *p,unsigned int z,int flags){(void)n;(void)z;(void)flags;strcpy(p,"fixture-ca");return mode==2 ? 10:-1;}\nstatic int AddPart(char *p,const char *n,unsigned int z){(void)z;strcat(p,"/");strcat(p,n);return 1;}\nint amihass_network_running(void){return mode!=0;}\nvoid amihass_erase(void *p,unsigned long n){memset(p,0,n);}\nstatic void Delay(int n){(void)n;}void nd_panel_wait(struct NDPanel *p,unsigned long e,unsigned long t){(void)p;(void)e;(void)t;Delay(5);}\nstruct NDPanel *nd_panel_open(const char *title,const struct NDPanelField *f,unsigned int n,const char **buttons,unsigned int count){unsigned int i;assert(strstr(title,"installation health")&&n==10&&count==2&&!strcmp(buttons[0],"Check again"));++opens;assert(!strcmp(f[1].value,AMIHASS_CONFIG_FILE));for(i=0;i<n;++i){assert(!f[i].limit&&!strstr(f[i].value,"PRIVATE-FIXTURE-TOKEN")&&!strstr(f[i].value,"private.invalid"));}assert(strlen(f[5].value)<=48&&strlen(f[7].value)<=48&&strlen(f[9].value)<=48);if(!mode)assert(strstr(f[0].value,"Stopped")&&strstr(f[2].value,"invalid")&&strstr(f[3].value,"Missing")&&strstr(f[6].value,"No ready"));if(mode==2)assert(strstr(f[2].value,"recovered")&&strstr(f[5].value,"Configured CA")&&strstr(f[8].value,"found"));return &panel;}\nint nd_panel_event(struct NDPanel *p){(void)p;return checks++ ? 101:100;}void nd_panel_close(struct NDPanel *p){assert(p==&panel);}\n'
ending='\nint main(void){for(mode=0;mode<3;++mode){opens=checks=0;amihass_health_ui();assert(opens==2);}puts("Health: missing/present installation, recovered cfg, service, executable, network and CA recheck; credentials omitted.");return 0;}\n'
with tempfile.TemporaryDirectory() as t:
 p=Path(t);(p/'check.c').write_text(prelude+s[a:b]+ending);subprocess.run([os.environ.get('CC','cc'),'-std=c99','-I'+str(root/'SDK'),'-I'+str(root/'include'),str(p/'check.c'),'-o',str(p/'check')],check=True);subprocess.run([str(p/'check')],check=True)
